import numpy as np, time
from sklearn.datasets import make_classification
from sklearn.calibration import CalibratedClassifierCV
from sklearn.linear_model import LogisticRegression
from sklearn.svm import LinearSVC
from sklearn.frozen import FrozenEstimator
from sklearn.base import clone

X,y=make_classification(n_samples=90,n_features=6,n_informative=4,n_redundant=0,random_state=0)
for est in [None, LogisticRegression(max_iter=1000, random_state=0), LinearSVC(random_state=0)]:
 for method in ['sigmoid','isotonic','temperature']:
  for ensemble in ['auto',True,False]:
   t=time.time()
   try:
    c=CalibratedClassifierCV(estimator=clone(est) if est else None, method=method, cv=3, ensemble=ensemble).fit(X,y)
    p=c.predict_proba(X[:5])
    print(type(est).__name__ if est else 'default',method,ensemble,len(c.calibrated_classifiers_), p.shape, p[0], p.sum(1),time.time()-t)
   except Exception as e:
    print('ERR',type(est).__name__ if est else 'default',method,ensemble,type(e).__name__,e)
PY"}

