import warnings
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from sklearn.base import BaseEstimator, ClassifierMixin
from sklearn.inspection import DecisionBoundaryDisplay
from sklearn.linear_model import LogisticRegression, LinearRegression
from sklearn.cluster import KMeans
from sklearn.ensemble import IsolationForest
from sklearn.exceptions import NotFittedError

X=np.array([[0.,0.],[1.,1.],[2.,2.],[3.,3.],[0.,1.],[1.,0.],[2.,3.],[3.,2.]])
yb=np.array([0,0,1,1,0,0,1,1])
ym=np.array([0,1,2,0,1,2,0,1])
for est,y,rm in [(LogisticRegression(max_iter=1000).fit(X,yb),yb,'auto'),(LogisticRegression(max_iter=1000).fit(X,ym),ym,'predict_proba'),(LogisticRegression(max_iter=1000).fit(X,ym),ym,'predict'),(LinearRegression().fit(X,yb.astype(float)),yb,'auto'),(KMeans(n_clusters=2, random_state=0,n_init=10).fit(X),yb,'auto'),(IsolationForest(random_state=0).fit(X),yb,'auto')]:
 try:
  d=DecisionBoundaryDisplay.from_estimator(est,X,grid_resolution=8,response_method=rm,target_colors=None)
  print(type(est).__name__, rm, 'nclasses',d.n_classes,'shape',d.response.shape,'surf',type(d.surface_).__name__, 'xlabel',repr(d.xlabel), 'target_colors_',hasattr(d,'target_colors_'))
 except Exception as e:
  print(type(est).__name__,rm,'ERR',type(e).__name__,e)
 plt.close('all')

# custom generic
class GenericPredictor(BaseEstimator):
    def __init__(self, values): self.values=values
    def fit(self,X,y=None): self.fitted_=True; return self
    def predict(self,X): return np.resize(np.asarray(self.values), X.shape[0])

for vals in [[0,1,2],[0,1],np.linspace(0,1,30)]:
 est=GenericPredictor(vals).fit(X)
 try:
  d=DecisionBoundaryDisplay.from_estimator(est,X,grid_resolution=5)
  print('generic',np.asarray(vals).shape,d.n_classes,d.response.shape)
 except Exception as e:
  print('generic err',type(e).__name__,e)
 plt.close('all')
# multilabel custom
class MultiOutClf(ClassifierMixin, BaseEstimator):
    def __init__(self): self.classes_=np.array([[0,1],[0,1]])
    def fit(self,X,y): return self
    def predict(self,X): return np.ones((X.shape[0],2))
    def predict_proba(self,X): return [np.ones((X.shape[0],2))/2]*2
try:
 d=DecisionBoundaryDisplay.from_estimator(MultiOutClf(),X,grid_resolution=5)
 print(d)
except Exception as e:
 print('multioutclf',type(e).__name__,e)

# multioutput regressor
Y=np.c_[yb,yb[::-1]]
r=LinearRegression().fit(X,Y)
try:
 d=DecisionBoundaryDisplay.from_estimator(r,X,grid_resolution=5)
 print('regmulti',d)
except Exception as e:
 print('regmulti',type(e).__name__,e)

# dataframe
Xd=pd.DataFrame(X,columns=['foo','bar'])
d=DecisionBoundaryDisplay.from_estimator(LogisticRegression(max_iter=1000).fit(Xd,yb),Xd,grid_resolution=5)
print('df labels',repr(d.xlabel),repr(d.ylabel),d.response.shape)

# invalid
est=LogisticRegression(max_iter=1000).fit(X,yb)
for kwargs in [dict(grid_resolution=1),dict(grid_resolution=0),dict(eps=-1),dict(plot_method='foo')]:
 try: DecisionBoundaryDisplay.from_estimator(est,X,**kwargs)
 except Exception as e: print(kwargs,type(e).__name__,str(e))
for XX in [X[:, :1], np.c_[X,X[:,0]]]:
 try: DecisionBoundaryDisplay.from_estimator(est,XX,grid_resolution=5)
 except Exception as e: print('features',XX.shape,type(e).__name__,str(e))
try: DecisionBoundaryDisplay.from_estimator(LogisticRegression(),X)
except Exception as e: print('unfit',type(e).__name__,str(e)[:100])
PY"}

