import numpy as np, warnings
from sklearn.base import BaseEstimator, ClassifierMixin
from sklearn.model_selection import cross_validate, cross_val_score, KFold, ShuffleSplit
from sklearn.datasets import make_classification
from sklearn.linear_model import LogisticRegression

class MarkerClassifier(ClassifierMixin, BaseEstimator):
    def fit(self, X, y):
        if np.any(X[:, 0] > 100):
            raise RuntimeError("marker present")
        self.classes_ = np.unique(y)
        self._pos = X[y == self.classes_[1]].mean(axis=0)
        self._neg = X[y == self.classes_[0]].mean(axis=0)
        return self
    def predict(self, X):
        d1 = ((X - self._pos) ** 2).sum(axis=1)
        d0 = ((X - self._neg) ** 2).sum(axis=1)
        return np.where(d1 < d0, self.classes_[1], self.classes_[0])

class AlwaysFail(ClassifierMixin, BaseEstimator):
    def fit(self, X, y):
        raise ValueError("always fails")
    def predict(self, X):
        return np.zeros(X.shape[0], dtype=int)

X, y = make_classification(n_samples=60, n_features=6, n_informative=3, random_state=0)
X[0, 0] = 999.0
def dict_scorer(est, X, y):
    from sklearn.metrics import accuracy_score, f1_score
    return {"acc": accuracy_score(y, est.predict(X)), "f1": f1_score(y, est.predict(X))}
with warnings.catch_warnings(record=True) as w:
    warnings.simplefilter("always")
    r = cross_validate(MarkerClassifier(), X, y, cv=KFold(3), scoring=dict_scorer, error_score=-1.0, return_train_score=True)
    print(r['test_acc'], r['test_f1'], r['train_acc'])
    print([x.category.__name__ for x in w])
# scoring failure where scorer partially fails: check error_score on those folds
try:
    cross_validate(AlwaysFail(), X, y, cv=3, error_score=-2)
except ValueError as e:
    print("all fail:", str(e)[:60])
# ShuffleSplit
try:
    cross_val_score(LogisticRegression(), X, y, cv=ShuffleSplit(2, random_state=0))
except ValueError as e:
    print("SS err", e)
