class NearestCentroidClassifier(ClassifierMixin, BaseEstimator):
    """Small deterministic classifier whose ``fit`` can be made to fail.

    ``fit`` raises when the training data contains a sample whose first
    feature is larger than ``marker``; this makes it possible to fail only a
    subset of the cross-validation folds.
    """

    def __init__(self, marker=100.0):
        self.marker = marker

    def fit(self, X, y):
        X = np.asarray(X)
        if np.any(X[:, 0] > self.marker):
            raise RuntimeError("marker sample present in the training data")
        self.classes_ = np.unique(y)
        self.centroids_ = np.array([X[y == c].mean(axis=0) for c in self.classes_])
        return self

    def predict(self, X):
        X = np.asarray(X)
        distances = ((X[:, None, :] - self.centroids_[None, :, :]) ** 2).sum(axis=2)
        return self.classes_[np.argmin(distances, axis=1)]


