    """Classifier whose ``fit`` always fails."""

    def fit(self, X, y):
        raise ValueError("this estimator cannot fit")

    def predict(self, X):
        return np.zeros(np.shape(X)[0], dtype=int)


class RecordingClassifier(ClassifierMixin, BaseEstimator):
    """Classifier that records the metadata it receives in ``fit``."""

    def fit(self, X, y, sample_weight=None):
        self.classes_ = np.unique(y)
        self.n_fit_samples_ = np.shape(X)[0]
        self.sample_weight_ = (
            None if sample_weight is None else np.asarray(sample_weight)
        )
        return self

    def predict(self, X):
        return np.full(np.shape(X)[0], self.classes_[0])


