from sklearn.neighbors import NearestNeighbors
from sklearn.exceptions import NotFittedError, DataConversionWarning, InvalidParameterError

X=np.array([[0.,0.],[1.,0.],[0.,2.],[2.,2.]])
# invalid construction/fit validation
for kwargs in [dict(n_neighbors=0),dict(radius=-1),dict(algorithm='x'),dict(leaf_size=0),dict(p=0),dict(metric='bad'),dict(n_jobs='x')]:
    try:
        n=NearestNeighbors(**kwargs).fit(X)
        print('accepted',kwargs)
    except Exception as e: print(kwargs,'->',type(e).__name__,str(e).splitlines()[0])
# dispatch
for kwargs in [dict(algorithm='kd_tree',metric='cosine'),dict(algorithm='kd_tree',metric=lambda x,y:0),dict(algorithm='ball_tree',p=.5),dict(algorithm='kd_tree',p=.5),dict(algorithm='brute',p=.5),dict(algorithm='kd_tree',metric='minkowski',metric_params={'w':[1,1]}),dict(algorithm='brute',metric='minkowski',metric_params={'w':[1,1]})]:
    try:
        with warnings.catch_warnings(record=True) as w:
            warnings.simplefilter('always')
            n=NearestNeighbors(**kwargs).fit(X)
        print(kwargs,'fit ok ',n._fit_method,n.effective_metric_,[(type(z.message).__name__,str(z.message)[:60]) for z in w])
    except Exception as e: print(kwargs,'ERR',type(e).__name__,str(e).splitlines()[0])
