{"command": "python - <<'PY'
import numpy as np
from sklearn.base import BaseEstimator, TransformerMixin, ClassifierMixin
from sklearn.utils.validation import validate_data, check_is_fitted
from sklearn.utils.multiclass import check_classification_targets
from sklearn.utils._tags import get_tags
import sklearn.utils.estimator_checks as ec

class NoOp(BaseEstimator):
    def __init__(self, param=1): self.param=param
    def fit(self, X, y=None):
        X = validate_data(self, X)
        return self

class Center(TransformerMixin, BaseEstimator):
    def __init__(self, scale=1.0): self.scale=scale
    def fit(self, X, y=None):
        X = validate_data(self, X)
        self.mean_ = X.mean(axis=0)
        return self
    def transform(self, X):
        X = validate_data(self, X, reset=False)
        return (X - self.mean_) * self.scale

class Centroid(ClassifierMixin, BaseEstimator):
    def __init__(self, shrink=0.0): self.shrink=shrink
    def fit(self, X, y):
        check_classification_targets(y)
        X, y = validate_data(self, X, y=y)
        self.classes_, y_idx = np.unique(y, return_inverse=True)
        self.centroids_ = np.vstack([X[y_idx==i].mean(axis=0) for i in range(len(self.classes_))])
        return self
    def predict(self, X):
        check_is_fitted(self)
        X = validate_data(self, X, reset=False)
        d = ((X[:,None,:] - self.centroids_[None,:,:])**2).sum(-1)
        return self.classes_[np.argmin(d, axis=1)]

for est in [NoOp(), Center(), Centroid()]:
    print(type(est).__name__, get_tags(est))

checks = [
    ec.check_estimator_cloneable, ec.check_estimator_repr,
    ec.check_no_attributes_set_in_init, ec.check_fit_score_takes_y,
    ec.check_estimators_overwrite_params, ec.check_dont_overwrite_parameters,
    ec.check_estimators_fit_returns_self, ec.check_readonly_memmap_input,
    ec.check_estimators_unfitted, ec.check_do_not_raise_errors_in_init_or_set_params,
    ec.check_n_features_in_after_fitting, ec.check_mixin_order,
    ec.check_positive_only_tag_during_fit,
]
for est in [NoOp(), Center(), Centroid()]:
    for c in checks:
        try:
            c(type(est).__name__, est)
        except Exception as e:
            print('FAIL', type(est).__name__, c.__name__, type(e).__name__, str(e)[:300])
    print('api checks done', type(est).__name__)

legacy = [
    ec.check_estimators_dtypes, ec.check_estimators_empty_data_messages,
    ec.check_estimators_nan_inf, ec.check_estimators_pickle,
    ec.check_fit2d_1sample, ec.check_fit2d_1feature, ec.check_fit1d,
    ec.check_fit2d_predict1d, ec.check_get_params_invariance,
    ec.check_set_params, ec.check_fit_idempotent, ec.check_fit_check_is_fitted,
    ec.check_n_features_in, ec.check_methods_subset_invariance,
    ec.check_methods_sample_order_invariance,
]
for est in [NoOp(), Center(), Centroid()]:
    for c in legacy:
        try:
            c(type(est).__name__, est)
        except Exception as e:
            print('LEGACY FAIL', type(est).__name__, c.__name__, type(e).__name__, str(e)[:300])
    print('legacy checks done', type(est).__name__)

trans=[ec.check_transformer_general, ec.check_transformer_data_not_an_array,
       ec.check_transformers_unfitted, ec.check_pipeline_consistency]
for est in [NoOp(), Center()]:
    for c in trans:
        try: c(type(est).__name__, est)
        except Exception as e: print('TRANS FAIL', type(est).__name__, c.__name__, type(e).__name__, str(e)[:300])
    print('trans done', type(est).__name__)

classif=[ec.check_classifiers_one_label, ec.check_classifiers_train,
