    """A deterministic transformer which validates X in fit and transform."""

    def __init__(self, scale=1.0):
        self.scale = scale

    def fit(self, X, y=None):
        X = validate_data(self, X)
        self.mean_ = X.mean(axis=0)
        return self

    def transform(self, X):
        X = validate_data(self, X, reset=False)
        return (X - self.mean_) * self.scale


class _PermissiveTransformer(TransformerMixin, BaseEstimator):
    """A transformer which never validates X."""

    def __init__(self):
        pass

    def fit(self, X, y=None):
        return self

    def transform(self, X):
        return np.asarray(X)


class _BadOneDimensionalTransformer(TransformerMixin, BaseEstimator):
    """A transformer whose transform accepts a 1-dimensional X."""

    def __init__(self):
        pass

    def fit(self, X, y=None):
        validate_data(self, X)
        return self

    def transform(self, X):
        return np.asarray(X)


class _CentroidClassifier(ClassifierMixin, BaseEstimator):
    """A small deterministic nearest-centroid classifier."""

    def __init__(self, shrink=0.0):
        self.shrink = shrink

    def fit(self, X, y):
        check_classification_targets(y)
        X, y = validate_data(self, X, y=y)
        self.classes_, y_idx = np.unique(y, return_inverse=True)
        self.centroids_ = np.vstack(
            [X[y_idx == i].mean(axis=0) for i in range(len(self.classes_))]
        )
        return self

    def predict(self, X):
        check_is_fitted(self)
        X = validate_data(self, X, reset=False)
        distances = ((X[:, np.newaxis, :] - self.centroids_[np.newaxis]) ** 2).sum(
            axis=-1
        )
        return self.classes_[np.argmin(distances, axis=1)]


