def test_check_estimator_integration(estimator, expected_checks):
    """A conforming built-in estimator should pass its category-specific checks."""
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        results = check_estimator(estimator, legacy=True, on_skip=None)

    assert results
    assert {result["status"] for result in results} <= {"passed", "skipped"}
    assert expected_checks <= {result["check_name"] for result in results}
    assert not any(
        isinstance(warning.message, EstimatorCheckFailedWarning) for warning in caught
    )
    for result in results:
        assert result["estimator"] is estimator
        assert result["expected_to_fail"] is False
        assert result["expected_to_fail_reason"] == "Check is not expected to fail"
        if result["status"] == "passed":
            assert result["exception"] is None


