from sklearn.utils.multiclass import check_classification_targets, type_of_target
from sklearn.utils.validation import check_is_fitted, validate_data


class _NoOpEstimator(BaseEstimator):
    """A minimal estimator that validates X and implements fit only."""

    def __init__(self, param=1):
        self.param = param

    def fit(self, X, y=None):
        validate_data(self, X)
        return self


class _NoFeatureTrackingEstimator(BaseEstimator):
    """A fit-only estimator which does not create n_features_in_."""

    def __init__(self, param=1):
        self.param = param

    def fit(self, X, y=None):
        return self


class _NoValidationEstimator(BaseEstimator):
    """An estimator which deliberately skips validation in fit."""

    def __init__(self, param=1):
        self.param = param

    def fit(self, X, y=None):
        return self


class _CenterTransformer(TransformerMixin, BaseEstimator):
    """A deterministic transformer which validates X in fit and transform."""

    def __init__(self, scale=1.0):
        self.scale = scale

    def fit(self, X, y=None):
        X = validate_data(self, X)
        self.mean_ = X.mean(axis=0)
        return self

    def transform(self, X):
        X = validate_data(self, X, reset=False)
        return (X - self.mean_) * self.scale


class _PermissiveTransformer(TransformerMixin, BaseEstimator):
    """A transformer which never validates X."""

    def __init__(self):
        pass

    def fit(self, X, y=None):
        return self

    def transform(self, X):
        return np.asarray(X)


class _BadOneDimensionalTransformer(TransformerMixin, BaseEstimator):
    """A transformer whose transform accepts a 1-dimensional X."""

    def __init__(self):
        pass

    def fit(self, X, y=None):
        validate_data(self, X)
        return self

    def transform(self, X):
        return np.asarray(X)


class _CentroidClassifier(ClassifierMixin, BaseEstimator):
    """A small deterministic nearest-centroid classifier."""

    def __init__(self, shrink=0.0):
        self.shrink = shrink

    def fit(self, X, y):
        check_classification_targets(y)
        X, y = validate_data(self, X, y=y)
        self.classes_, y_idx = np.unique(y, return_inverse=True)
        self.centroids_ = np.vstack(
            [X[y_idx == i].mean(axis=0) for i in range(len(self.classes_))]
        )
        return self

    def predict(self, X):
        check_is_fitted(self)
        X = validate_data(self, X, reset=False)
        distances = ((X[:, np.newaxis, :] - self.centroids_[np.newaxis]) ** 2).sum(
            axis=-1
        )
        return self.classes_[np.argmin(distances, axis=1)]


class _AlwaysZeroClassifier(ClassifierMixin, BaseEstimator):
    """A classifier which accepts any target but always predicts zero."""

    def __init__(self, constant=0):
        self.constant = constant

    def fit(self, X, y):
        X, y = validate_data(self, X, y=y)
        self.classes_ = np.unique(y)
        return self

    def predict(self, X):
        return np.zeros(np.asarray(X).shape[0], dtype=int)


class _BinaryOnlyClassifier(_CentroidClassifier):
    """A classifier whose tags and validation restrict it to binary targets."""

    def __sklearn_tags__(self):
        tags = super().__sklearn_tags__()
        tags.classifier_tags.multi_class = False
        return tags

    def fit(self, X, y):
        if type_of_target(y) != "binary":
            raise ValueError("Only binary classification is supported.")
        return super().fit(X, y)


