def test_check_estimator_expected_failure_is_xfail_and_warns():
    reason = "this custom estimator intentionally misses n_features_in_"
    check_name = "check_n_features_in_after_fitting"

    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        results = check_estimator(
            _NoFeatureTrackingEstimator(),
            legacy=False,
            expected_failed_checks={check_name: reason},
            on_fail="warn",
            on_skip=None,
        )

    failures = [result for result in results if result["check_name"] == check_name]
    assert len(failures) == 1
    failure = failures[0]
    assert failure["status"] == "xfail"
    assert failure["expected_to_fail"] is True
    assert failure["expected_to_fail_reason"] == reason
    assert isinstance(failure["exception"], AssertionError)
    assert "does not set the `n_features_in_` attribute" in str(failure["exception"])

    check_warnings = [
        warning.message
        for warning in caught
        if isinstance(warning.message, EstimatorCheckFailedWarning)
    ]
    assert len(check_warnings) == 1
    warning = check_warnings[0]
    assert warning.check_name == check_name
    assert warning.status == "xfail"
    assert warning.expected_to_fail is True
    assert warning.expected_to_fail_reason == reason


