def _check_name(check):
    """Return the name of a generated check without relying on pytest ids."""
    while hasattr(check, "__wrapped__"):
        check = check.__wrapped__
    if hasattr(check, "func"):
        return check.func.__name__
    return check.__name__


def _check_from_parameter(item):
    """Extract the check from either a plain tuple or a pytest ParameterSet."""
    return item.values[1] if hasattr(item, "values") else item[1]


def _names_from_generator(estimator, **kwargs):
    return [_check_name(check) for _, check in estimator_checks_generator(estimator, **kwargs)]


